/**
 * Exo ADI driver: mirrors PolyBench/C adi.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "adi.h"

/* Include the Exo-generated kernel header. */
#include "generated/adi/adi.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	u[i][j] =  (DATA_TYPE)(i + n-j) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static 
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n)) 
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("u");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, u[i][j]);
    }
  POLYBENCH_DUMP_END("u");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *  # import scheduling primitives (e.g., simplify)
from exo.libs.memories import DRAM


@proc
def kernel_adi(
    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,  # kept for interface compatibility; not used in the optimized kernel
    q: DATA_TYPE[n, n] @ DRAM,  # kept for interface compatibility; not used in the optimized kernel
):
    """
    Optimized ADI kernel.

    Main changes versus the straightforward implementation:

    - Replace the original 2D p[i,j] / q[i,j] working arrays with four
      1D temporaries:
          p_col[j], q_col[j] for the column sweep;
          p_row[j], q_row[j] for the row sweep.
      Each is of length n and is reused across all lines and time steps.
      The original p, q arguments are still present in the signature
      but are not used by the computation.

      This reduces the active working set for the Thomas algorithm from
      O(n^2) to O(n) and keeps the line coefficients in L1 cache.

    - Hoist and reuse scalar combinations that appear many times:
          a, b, c, d, e, f as in the original ADI scheme;
          one_plus_2d = 1 + 2*d;
          one_plus_2a = 1 + 2*a;
          denom / inv_denom and denom2 / inv_denom2 in the sweeps
      to cut the number of divisions in half inside each forward sweep.

    - The structure of the ADI method (time loop, then column sweep,
      then row sweep) and the boundary conditions are unchanged,
      so the resulting u is numerically identical to the original code.
    """
    assert n > 2

    # ADI scalar coefficients (loop-invariant).
    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Frequently used combinations.
    one_plus_2d: DATA_TYPE
    one_plus_2a: DATA_TYPE

    # Precompute coefficients once per kernel call.
    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    one_plus_2d = 1.0 + 2.0 * d
    one_plus_2a = 1.0 + 2.0 * a

    # 1D temporaries for the tridiagonal solves.
    # These buffers are reused across all lines (columns/rows) and time steps.
    # They play the role of p[i,*] / q[i,*] in the original implementation,
    # but only one line at a time is kept in memory.
    p_col: DATA_TYPE[n] @ DRAM
    q_col: DATA_TYPE[n] @ DRAM
    p_row: DATA_TYPE[n] @ DRAM
    q_row: DATA_TYPE[n] @ DRAM

    # Time-stepping loop: u is updated tsteps times.
    for t in seq(0, tsteps):
        # ----------------------------------------------------------
        # Column sweep: for each interior column i_col, solve a
        # tridiagonal system along the j-direction to obtain v[:, i_col]
        # from the current u.
        # ----------------------------------------------------------
        for i_col in seq(1, n - 1):
            # Dirichlet boundary at j = 0.
            v[0, i_col] = 1.0
            p_col[0] = 0.0
            q_col[0] = v[0, i_col]

            # Forward sweep (Thomas algorithm) along j: 1 <= j <= n-2.
            for j in seq(1, n - 1):
                # denom = a * p_col[j-1] + b
                denom = a * p_col[j - 1] + b
                # Reuse the reciprocal in both p_col and q_col updates
                # to avoid two divisions per iteration.
                inv_denom = 1.0 / denom

                # p[i,j] = -c / denom
                p_col[j] = -c * inv_denom

                # q[i,j] = ( -d*u[j,i-1] + (1+2d)*u[j,i] - f*u[j,i+1]
                #            - a*q[i,j-1] ) / denom
                q_col[j] = (
                    -d * u[j, i_col - 1]
                    + one_plus_2d * u[j, i_col]
                    - f * u[j, i_col + 1]
                    - a * q_col[j - 1]
                ) * inv_denom

            # Dirichlet boundary at j = n-1.
            v[n - 1, i_col] = 1.0

            # Backward substitution along j: j = 1..n-2 corresponds to
            # indices k = n-1-j running from n-2 down to 1.
            for j in seq(1, n - 1):
                v[n - 1 - j, i_col] = (
                    p_col[n - 1 - j] * v[n - j, i_col]
                    + q_col[n - 1 - j]
                )

        # ----------------------------------------------------------
        # Row sweep: for each interior row i_row, solve a tridiagonal
        # system along j to update u[i_row, : ] from v.
        # ----------------------------------------------------------
        for i_row in seq(1, n - 1):
            # Dirichlet boundary at j = 0.
            u[i_row, 0] = 1.0
            p_row[0] = 0.0
            q_row[0] = u[i_row, 0]

            # Forward sweep along j.
            for j in seq(1, n - 1):
                # denom2 = d * p_row[j-1] + e
                denom2 = d * p_row[j - 1] + e
                inv_denom2 = 1.0 / denom2

                # p[i,j] = -f / denom2
                p_row[j] = -f * inv_denom2

                # q[i,j] = ( -a*v[i-1,j] + (1+2a)*v[i,j] - c*v[i+1,j]
                #            - d*q[i,j-1] ) / denom2
                q_row[j] = (
                    -a * v[i_row - 1, j]
                    + one_plus_2a * v[i_row, j]
                    - c * v[i_row + 1, j]
                    - d * q_row[j - 1]
                ) * inv_denom2

            # Dirichlet boundary at j = n-1.
            u[i_row, n - 1] = 1.0

            # Backward substitution along j.
            for j in seq(1, n - 1):
                u[i_row, n - 1 - j] = (
                    p_row[n - 1 - j] * u[i_row, n - j]
                    + q_row[n - 1 - j]
                )


# Apply a light-weight simplification pass to clean up the IR.
# (No structural changes; just constant folding / dead-code elimination.)
kernel_adi = simplify(kernel_adi)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Precompute scalar coefficients used by the Exo kernel. */
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;

  DX = SCALAR_VAL(1.0) / (DATA_TYPE)n;
  DY = SCALAR_VAL(1.0) / (DATA_TYPE)n;
  DT = SCALAR_VAL(1.0) / (DATA_TYPE)tsteps;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_adi(/*ctxt=*/NULL,
             tsteps, n,
             (DATA_TYPE*)&mul1, (DATA_TYPE*)&mul2,
             (DATA_TYPE*)POLYBENCH_ARRAY(u),
             (DATA_TYPE*)POLYBENCH_ARRAY(v),
             (DATA_TYPE*)POLYBENCH_ARRAY(p),
             (DATA_TYPE*)POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

  return 0;
}
