    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
):
    # We update only interior points 1..n-2 in both directions.
    # Require at least a single interior cell in each dimension.
    assert n > 2

    #---------------------------------------------------------------------
    # Precompute scalar ADI coefficients.
    # These are invariant across all time and space loops and are kept
    # in registers by the C compiler.
    #---------------------------------------------------------------------
    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE
    g1: DATA_TYPE  # 1 + 2*d, used in column sweep
    g2: DATA_TYPE  # 1 + 2*a, used in row sweep

    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d
    g1 = 1.0 + 2.0 * d
    g2 = 1.0 + 2.0 * a

    #---------------------------------------------------------------------
    # Time-stepping loop: each iteration advances the solution u by one
    # ADI time step. We keep this loop sequential.
    #---------------------------------------------------------------------
    for t in seq(0, tsteps):
        #=============================================================
        # 1) Column sweep (implicit in the j-direction, explicit in i)
        #
        # We reorganize the computation into four phases:
        #   (a) initialize top boundary and line-solve state for all
        #       interior columns;
        #   (b) forward tridiagonal sweep along j, but iterating
        #       outermost over j and innermost over i;
        #   (c) initialize bottom boundary for all columns;
        #   (d) backward substitution along j, again with j outer.
        #
        # Compared to the original i-outer, j-inner structure, this
        # reordering preserves the j-direction recurrences but makes
        # accesses to the main grid u and the intermediate v more
        # cache-friendly: the innermost loop now walks contiguous
        # memory in the second (column) dimension.
        #=============================================================

        # (a) Initialize top boundary and starting p/q for each column.
        for i_col in seq(1, n - 1):
            v[0, i_col] = 1.0
            p[i_col, 0] = 0.0
            q[i_col, 0] = v[0, i_col]

        # (b) Forward sweep along j for all interior (j, i_col).
        #     j is outer to respect the Thomas recurrence; i_col is
        #     inner so that u[j, i_col-1..i_col+1] and v[j, i_col]
        #     are accessed with good spatial locality.
        for j_col in seq(1, n - 1):
            for i_col in seq(1, n - 1):
                denom1: DATA_TYPE
