                denom1 = a * p[i_col, j_col - 1] + b
                p[i_col, j_col] = -c / denom1

                rhs1 = (
                    -d * u[j_col, i_col - 1]
                    + g1 * u[j_col, i_col]
                    - f * u[j_col, i_col + 1]
                    - a * q[i_col, j_col - 1]
                )
                q[i_col, j_col] = rhs1 / denom1

        # (c) Initialize bottom boundary for each column.
        for i_col in seq(1, n - 1):
            v[n - 1, i_col] = 1.0

        # (d) Backward substitution along j to recover v[:, i_col].
        #     We again iterate j outer, i_col inner. For a fixed i_col,
        #     the recurrence runs from j = n-2 down to j = 1, which we
        #     express via indices (n - 1 - j_col) and (n - j_col).
        for j_col in seq(1, n - 1):
            for i_col in seq(1, n - 1):
                v[n - 1 - j_col, i_col] = (
                    p[i_col, n - 1 - j_col] * v[n - j_col, i_col]
                    + q[i_col, n - 1 - j_col]
                )

        #=============================================================
        # 2) Row sweep (implicit in the j-direction, explicit in i)
        #
        # Here the original ordering (i outer, j inner) already matches
        # the row-major layout of u and v, so we keep it. Each loop over
        # i_row is an independent 1D tridiagonal solve along j.
